void opFromToRotation(inout vec3 p, vec3 axisFrom, vec3 axisTo)
{
    axisFrom    = normalize(axisFrom);
    axisTo      = normalize(axisTo);

    vec3    axisCross   = cross(axisFrom, axisTo);
    float   angleBetween= acos(dot(axisTo, axisFrom));

    axisCross = normalize(axisCross);

    // quaternionFromAxisAngle
    float halfAngle     = angleBetween * 0.5;
    float sinHalfAngle  = sin(halfAngle);
    float cosHalfAngle  = cos(halfAngle);
    vec4 q = vec4(axisCross, cosHalfAngle);
    q.xyz *= sinHalfAngle;

    p += 2.0 * cross(q.xyz, cross(q.xyz, p) + q.w * p);
}
